import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"130/30","description":"","frontmatter":{"title":"130/30","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/one-thirty-thirty.md","filePath":"quant/one-thirty-thirty.md","lastUpdated":1789023840000}'),p={name:"quant/one-thirty-thirty.md"};function _(c,a,A,u,m,B){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="_130-30" tabindex="-1">130/30 <a class="header-anchor" href="#_130-30" aria-label="Permalink to &quot;130/30&quot;">​</a></h1><div class="epigraph"><p>130/30 用有限卖空把多头主动权重的对称性补上：看好的可以超配到超过权重上限，资金来自看空的 30%。</p><footer>—— Jacobs, Levy and Starer, On the Optimality of Long–Short Strategies, Financial Analysts Journal, 1998 前后对放松多头约束的讨论</footer></div><p><a href="/quant/long-short-equity">上一课</a>是双侧都可以到 100% 的中性或多空。130/30 的缺口是<strong>多头基准产品</strong>：净暴露保持约 100%，总暴露 160%，空头通常 30%。主干 <a href="/quant/portfolio-constraints">组合约束</a> 已写多头-only 的约束成本。本课写放松 30% 卖空值不值借券与跟踪误差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯多头主动：低配一只股票最多到权重 0，超配受集中度限制。信息在看空一侧被截断。允许 30% 卖空，把释放的资金加到多头，形成 130 多 / 30 空，净仍约 1。问题是：这 30% 的借券与主动风险，是否提高 IR 足以覆盖成本。若空头只是把多头约束「对称化」且信号在两侧同样有效，Jacobs–Levy 的逻辑说应当提高效率；若信号主要在多头流动性名字、空头都是借券贵的小盘，130/30 会毁价值。</p><p>与市场中性：130/30 保留几乎全部市场 beta，基准是指数，跟踪误差有限。客户买的是「增强指数」而不是绝对收益。评价应用超额与 TE，不是用中性基金的夏普。</p><h3 id="_30-不是魔术数字" tabindex="-1">30 不是魔术数字 <a class="header-anchor" href="#_30-不是魔术数字" aria-label="Permalink to &quot;30 不是魔术数字&quot;">​</a></h3><p>140/40、120/20 是同一族。最优空头比例取决于借券供给、基准集中度与信号双边性。固定 30 是产品营销与风险预算的折中。优化里应把空头比例当约束参数做稳健，而不是当理论最优。</p><p><span class="marginnote">130/30 的杠杆是总暴露 1.6，不是 1.3 倍净值的融资杠杆 ETF。重置与拖累不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在基准权重附近优化主动 \\(w-w_b\\)，约束 \\(\\sum w=1\\)、\\(\\sum w^-=0.3\\)、\\(w_i\\ge -c\\)。风险用相对 \\(\\Sigma\\)。借券成本进预期收益。对照：纯多头增强 vs 130/30 的扣费 IR/TE。执行：空头名单预审。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多头-only 的有效前沿被截断。放松卖空把一部分截断补回，主动风险的每单位 IR 上升——若短腿可执行。不可执行时，优化器会把空头堆在少数可借名字，变成集中空头风险，效率下降。</p>',13)),(e(),s(E,null,{default:r(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Long%5B%22%E7%BA%AF%E5%A4%9A%E5%A4%B4%20%E4%BD%8E%E9%85%8D%E6%88%AA%E6%96%AD%E5%9C%A8%200%22%5D%20--%3E%20Rel%5B%22%E7%9B%B8%E5%AF%B9%E5%9F%BA%E5%87%86%E4%BC%98%E5%8C%96%22%5D%0A%20%20Short30%5B%22%E5%85%81%E8%AE%B8%2030%25%20%E7%A9%BA%22%5D%20--%3E%20Rel%0A%20%20Rel%20--%3E%20Prod%5B%22%E5%87%80%E7%BA%A6%20100%25%20%E6%80%BB%20160%25%22%5D%0A%20%20Loan%5B%22%E5%80%9F%E5%88%B8%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20Feas%5B%22%E7%9F%AD%E8%85%BF%E6%98%AF%E5%90%A6%E7%9C%9F%E8%83%BD%E5%AF%B9%E7%A7%B0%E5%8C%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2008 年式的做空限制会瞬间把 130/30 变回残缺多头。基准若是不可做空的指数（部分 A 股），产品结构要改，见中国课。费用高于指数增强，后课费用复合要单独算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>130/30 是带有限卖空的增强指数，不是市场中性。</li><li>价值取决于信号双边性与借券；30% 是产品参数。</li><li>评价用 TE 与超额，不用绝对夏普。</li><li>出处：Jacobs, Levy and Starer 对多空相对多头约束的讨论，<em>FAJ</em>。</li></ul>',4))])}const T=i(p,[["render",_]]);export{q as __pageData,T as default};
